40	bool llvm::parseAssemblyInto(MemoryBufferRef F, Module *M,
41	                             ModuleSummaryIndex *Index, SMDiagnostic &Err,
42	                             SlotMapping *Slots,
43	                             DataLayoutCallbackTy DataLayoutCallback,
44	                             AsmParserContext *ParserContext) {
